// CoordinatorComponent is the test component `coordinator` as the
// profile's runtime drives it (docs/SCE_TEST_PROFILE.md §12.3).
//
// It owns the machine of the policy above, unchanged, and reaches it only
// through the doors the engine already has: the machine's sends on a port leave
// through the test-port processor and its PTCs through the test-component
// invoker, both registered here over the component's runtime context
// (docs/adr/0084), and each round's snapshot is the one external event every
// branch is a transition on. The runtime never reports a PTC's completion to
// the engine: a done branch reads it from the snapshot, so the engine cancels
// every PTC it started when the invoking state is exited, which is P9's kill.
// One goroutine; the engine's scheduler takes no part, since a component sends
// nothing delayed.
//
// The machine is built when the component starts, around a policy the context
// is already set on, and there is none before. The zero value is a component
// that has not started.
type CoordinatorComponent struct {
	machine *sce.Engine[CoordinatorState, CoordinatorEvent]
}

// CoordinatorComponent is driven by the profile's runtime.
var _ scetestprofile.ComponentMachine = (*CoordinatorComponent)(nil)

// Start builds the machine with context and starts it.
func (c *CoordinatorComponent) Start(context *scetestprofile.ComponentContext) {
	policy := NewCoordinatorPolicy()
	// The session is named by the component, and named rather than drawn. The
	// name is `mtc` or the id of the `<invoke>` that creates the PTC
	// (ComponentContext.Create, which creates nothing under a name its
	// configuration has no PTC of), and every `<invoke id>` is refused where
	// its document is parsed unless it is an XML Name, which is an Nmtoken
	// (docs/adr/0045). The refusal below is therefore unreachable for a
	// component a generated one creates.
	if err := policy.SetSessionID(context.Name()); err != nil {
		panic("a test component's name is an XML Name, which names a session: " + err.Error())
	}
	policy.sceTestContext = context
	machine := sce.NewEngine[CoordinatorState, CoordinatorEvent](&policy)
	// P6: a send on a port is appended to the queue of the port it is connected
	// to, or handed to the system adapter where it is mapped. A test-port send
	// always carries its template's value (`forge::static_lowering`,
	// `StaticTarget::test_message`).
	machine.RegisterEventProcessor("http://sce.dev/ext/test-port", func(request sce.HostSendRequest) []sce.HostSendResponse {
		if request.Value == nil {
			panic("a test-port send carries its template's value")
		}
		context.Send(request.Target, scetestprofile.Message{Event: request.EventName, Value: request.Value})
		return nil
	})
	// P9: the start of a PTC's invocation creates and starts it, and its cancel
	// removes it, whether it is still running or already done.
	machine.RegisterInvoker("http://sce.dev/ext/test-component", func(event sce.HostInvokeEvent) *sce.HostInvokeResponse {
		if event.Start != nil {
			context.Create(event.Start.InvokeID)
		}
		if event.Cancel != nil {
			context.Kill(event.Cancel.InvokeID)
		}
		return nil
	})
	// A test component holds no script engine (`needs_script_engine` is false
	// for every one), so its start has no script session to be refused for.
	if err := machine.Initialize(); err != nil {
		panic("a test component's machine has no script session to fail: " + err.Error())
	}
	c.machine = machine
}

